import XCTest

// MARK: - Container fixtures (PR 4 plan §7.2)
//
// The facts the container UI tests, lifecycle K tests and the storyboard
// share: landmark texts, owners and expand titles of `containers-parity`,
// `containers-expand`, `captions-parity` and `containers-dense`, as the
// fixtures helper tabulated them (`fixtures/landmarks.md` in the PR 4 data
// directory, generated by `swift Tools/make-fixtures.swift --landmarks` at
// the bytes `Fixtures/SHA256SUMS` pins). A leaf's owner is the id its
// TextKit 2 row carries (`tk2-row:<owner>`); its sentinel starts its text.

/// One text leaf of a container fixture.
struct ContainerLeaf: Sendable, CustomStringConvertible {
    let sentinel: String
    let owner: String
    /// What the leaf's accessibility label starts with: the sentinel and
    /// the space after it, so `KP-QUOTE-OUTER` never matches
    /// `KP-QUOTE-OUTER-AFTER`; the whole label for a leaf whose text is the
    /// sentinel alone (`CXOPENSENTINEL`).
    let prefix: String

    init(_ sentinel: String, _ owner: String, alone: Bool = false) {
        self.sentinel = sentinel
        self.owner = owner
        prefix = alone ? sentinel : sentinel + " "
    }

    var description: String { "\(sentinel) (\(owner))" }
}

/// An expand: its title (the button's label; the value is "Expanded" or
/// "Collapsed"), its block id (the key of `model.expandedBlocks`), its
/// first and last body leaves, and the nested expand inside it, if any.
struct ContainerExpand: Sendable {
    let title: String
    let id: String
    let first: ContainerLeaf
    let last: ContainerLeaf
    var nestedTitle: String?
    var nestedFirst: ContainerLeaf?
    var nestedLast: ContainerLeaf?
}

/// A linked span inside a leaf: the link's own text, and the exact URL a
/// tap must open (nil: a whitespace-only href, which must open nothing).
struct ContainerLink: Sendable {
    let leaf: ContainerLeaf
    let linkText: String
    let url: String?
    /// The root heading the leaf sits under (navigation).
    let section: String
}

/// `-scrollToFraction` for prepared top-level block `index` of `count`:
/// the block's middle, which `ReaderView.fractionTarget` maps back to
/// `Int(f × count) == index`.
func containerFraction(_ index: Int, of count: Int) -> String {
    String(format: "%.4f", (Double(index) + 0.5) / Double(count))
}

