/// `containers-expand`: 554 top-level blocks. The search chain at block 0,
/// a plain tail, the tall expand (300 paragraphs) at 305, and five open
/// expands CE-OPEN-1 … 5 at 346, 386, 427, 470, 513, each under its own h2
/// one block earlier and four screens of filler apart.
enum ContainersExpand {
    static let fixture = "containers-expand"
    static let preparedBlocks = 554

    static let chainTitles = ["CE-CHAIN outer expand: the search opens this chain", "CE-CHAIN-L2 nested expand",
                              "CE-CHAIN-L3 deepest expand"]
    static let sentinel = ContainerLeaf("CXOPENSENTINEL", "0.0.2.2.1", alone: true)
    static let sentinelNeighbours = [ContainerLeaf("CE-CHAIN-L3-A", "0.0.2.2.0"), ContainerLeaf("CE-CHAIN-L3-B", "0.0.2.2.2")]
    static let s1 = "CE-S1 Plain tail: the static scroll after the search-opened chain"

    static let s2Index = 304
    static let s2 = "CE-S2 Tall expand: 300 plain paragraphs (testK8)"
    static let tall = ContainerExpand(
        title: "CE-TALL tall expand: 300 plain paragraphs", id: "0.305",
        first: ContainerLeaf("CE-TALL-001", "0.305.0"), last: ContainerLeaf("CE-TALL-300", "0.305.299")
    )

    /// The heading index of CE-OPEN-n's section (the expand is one later).
    static let openHeadingIndex = [345, 385, 426, 469, 512]
    /// CE-OPEN-n's body paragraph count (B01 … B<n>) and the index of its
    /// last paragraph in the body.
    private static let lastParagraph = [(25, 28), (28, 31), (30, 33), (32, 35), (35, 38)]

    /// CE-OPEN-n (1 … 5): 30, 33, 35, 37 and 40 leaves, a code child at
    /// `.12`, a list at `.8`, tasks at `.17` and a nested expand at `.22`.
    static func open(_ n: Int) -> ContainerExpand {
        let id = "0.\(openHeadingIndex[n - 1] + 1)"
        let (count, index) = lastParagraph[n - 1]
        let leaves = [30, 33, 35, 37, 40][n - 1]
        return ContainerExpand(
            title: "CE-OPEN-\(n) open expand \(n): \(leaves) leaves and a nested expand", id: id,
            first: ContainerLeaf("CE-OPEN-\(n)-B01", id + ".0"),
            last: ContainerLeaf("CE-OPEN-\(n)-B" + String(format: "%02ld", count), id + ".\(index)"),
            nestedTitle: "CE-OPEN-\(n)-NESTED nested expand of open expand \(n)",
            nestedFirst: ContainerLeaf("CE-OPEN-\(n)-N1", id + ".22.0"),
            nestedLast: ContainerLeaf("CE-OPEN-\(n)-N4", id + ".22.3")
        )
    }

    static func openHeading(_ n: Int) -> String {
        "CE-S\(n + 2) Open expand \(n) (testK5, testK6, testK7)"
    }

    static let end = ContainerLeaf("CE-END", "0.553")

    static func fraction(_ index: Int) -> String { containerFraction(index, of: preparedBlocks) }

    /// The top-level block index a containers-expand label sits at, from
    /// its sentinel (CE-TAIL-k at k + 1, CE-FILL-T-k at 305 + k, CE-FILL-n-k
    /// at CE-OPEN-n's index + k, a CE-OPEN-n title or leaf half a block
    /// below the expand's index, CE-TALL-… likewise, CE-S1 … CE-S7 at their
    /// heading); nil for any other label. `ContainerDriver.seek` steers by it.
    static func blockIndex(ofLabel label: String) -> Double? {
        let parts = label.split(separator: " ", maxSplits: 1).first.map { $0.split(separator: "-") } ?? []
        guard parts.count >= 2, parts[0] == "CE" else { return nil }
        let number = { (index: Int) -> Int? in parts.count > index ? Int(parts[index]) : nil }
        switch parts[1] {
        case "CHAIN": return 0
        case "END": return 553
        case "TALL": return 305.5
        case "TAIL": return number(2).map { Double($0 + 1) }
        case "FILL":
            guard parts.count >= 4, let k = number(3) else { return nil }
            if parts[2] == "T" { return Double(305 + k) }
            guard let n = number(2), (1 ... 5).contains(n) else { return nil }
            return Double(openHeadingIndex[n - 1] + 1 + k)
        case "OPEN":
            guard let n = number(2), (1 ... 5).contains(n) else { return nil }
            return Double(openHeadingIndex[n - 1] + 1) + 0.5
        default:
            guard parts[1].hasPrefix("S"), let n = Int(parts[1].dropFirst()), (1 ... 7).contains(n) else { return nil }
            return Double([1, 304, 345, 385, 426, 469, 512][n - 1])
        }
    }
}

