// MARK: - Interaction probe (`-interactionProbe`)

/// The About sheet's interaction-probe fields: task dispatches and URL
/// opens the document asked the host for, and the last of each.
struct ContainerProbe: Equatable, CustomStringConvertible {
    enum Identifier {
        static let taskDispatches = "probe-task-dispatches"
        static let taskLast = "probe-task-last"
        static let urlOpens = "probe-url-opens"
        static let urlLast = "probe-url-last"
    }

    let taskDispatches: Int
    let taskLast: String
    let urlOpens: Int
    let urlLast: String

    var description: String {
        "tasks \(taskDispatches) (last \(taskLast.isEmpty ? "-" : taskLast)), "
            + "urls \(urlOpens) (last \(urlLast.isEmpty ? "-" : urlLast))"
    }
}

// MARK: - Driver

/// Drives one launched ADFReader on a container fixture: leaves and their
/// engines, expands, navigation, search, About and the interaction probe.
/// Wraps the shared `ReaderDriver`; its About waits are the 30 s ones of
/// `CodeUIDriver` and `ListUIDriver` (on a loaded host one query can take
/// seconds).
@MainActor
struct ContainerDriver {
    let reader: ReaderDriver
    var app: XCUIApplication { reader.app }

    /// How long a `tk2-row` may take to appear or leave the tree after an
    /// engine change (as `CodeUIDriver.engineTimeout`).
    static let engineTimeout: TimeInterval = 30
    static let aboutTimeout: TimeInterval = 30

    /// `-rendererReset` (SwiftUI unless `textKit2`), `-rendererStats`,
    /// `-fontSizeStep 0` (Text Size taps never persist) and
    /// `-interactionProbe`; `fraction` lands on a block (`-scrollToFraction`).
    init(fixture: String, textKit2: Bool = false, fraction: String? = nil, extra: [String] = []) {
        var arguments = ["-fixture", fixture, "-rendererReset", "-rendererStats", "-fontSizeStep", "0",
                         "-interactionProbe"]
        if let fraction { arguments += ["-scrollToFraction", fraction] }
        if textKit2 { arguments.append("-textkit2") }
        reader = ReaderDriver(launching: arguments + extra)
    }

    /// Wraps a reader a test launched itself (the lifecycle K tests).
    init(wrapping reader: ReaderDriver) {
        self.reader = reader
    }

    func pause(_ seconds: TimeInterval = 1) {
        reader.pause(seconds)
    }

    // MARK: Leaves and engines

    /// `leaf`'s text under either renderer.
    func element(_ leaf: ContainerLeaf) -> XCUIElement {
        reader.element(labelPrefix: leaf.prefix)
    }

    /// The TextKit 2 row whose owner is exactly `owner`.
    func textKit2Row(owner: String) -> XCUIElement {
        app.descendants(matching: .any)
            .matching(identifier: ReaderDriver.Identifier.textKit2RowPrefix + owner).firstMatch
    }

    /// Whether `leaf` is drawn by a TextKit 2 row with its own owner and
    /// its own text, waiting up to `timeout`.
    func isTextKit2(_ leaf: ContainerLeaf, timeout: TimeInterval = ContainerDriver.engineTimeout) -> Bool {
        let row = textKit2Row(owner: leaf.owner)
        return row.waitForExistence(timeout: timeout) && row.label.hasPrefix(leaf.prefix)
    }

    /// Whether `leaf` has no TextKit 2 row, waiting up to `timeout` for one
    /// to leave the tree.
    func isSwiftUI(_ leaf: ContainerLeaf, timeout: TimeInterval = ContainerDriver.engineTimeout) -> Bool {
        let row = textKit2Row(owner: leaf.owner)
        return !row.exists || reader.waitForDisappearance(of: row, timeout: timeout)
    }

    /// A search match's per-owner fallback: `leaf`'s text is in the tree
    /// and at least partly in the viewport, and no TextKit 2 row owned by
    /// it is (waiting up to `timeout` for one to leave). Unlike
    /// `isSwiftUI`, a text that is not there, or not on screen, never
    /// passes. nil: it holds; otherwise what failed.
    func searchFallbackProblem(_ leaf: ContainerLeaf, timeout: TimeInterval = ContainerDriver.engineTimeout) -> String? {
        guard element(leaf).waitForExistence(timeout: 5) else { return "\(leaf): its text is not in the tree" }
        guard isSwiftUI(leaf, timeout: timeout) else { return "\(leaf) is still a TextKit 2 row while highlighted" }
        // No TextKit 2 row of the owner is left, so the element is its
        // SwiftUI text.
        let text = element(leaf)
        guard text.exists else { return "\(leaf): its text left the tree with its TextKit 2 row" }
        guard isPartlyShown(text) else {
            return "\(leaf): its SwiftUI text is not on screen (frame \(text.frame), viewport \(reader.viewport))"
        }
        return nil
    }

    /// A match's neighbour keeps TextKit 2: brings `leaf` at least partly
    /// into view first (drags of `step` points, > 0 toward the end, at most
    /// `maxDrags`; once it is in the tree they step toward it), then it must
    /// be its owner's TextKit 2 row. nil: it holds; otherwise what failed.
    func searchNeighbourProblem(_ leaf: ContainerLeaf, step: CGFloat, maxDrags: Int = 6) -> String? {
        if !isPartlyShown(element(leaf)) {
            var drags = 0
            while !isPartlyShown(element(leaf)), drags < maxDrags {
                _ = scroll(by: step, until: element(leaf), maxDrags: 1)
                drags += 1
            }
        }
        guard isPartlyShown(element(leaf)) else { return "\(leaf): the neighbour could not be brought into view" }
        return isTextKit2(leaf) ? nil : "\(leaf) left TextKit 2 (the fallback is per owner)"
    }

    /// The engine `leaf` must have in an arm: its own TextKit 2 row under
    /// TextKit 2 (`textKit2`), none under SwiftUI.
    func expectEngine(_ leaf: ContainerLeaf, textKit2: Bool, _ context: String,
                      file: StaticString = #filePath, line: UInt = #line)
    {
        if textKit2 {
            XCTAssertTrue(isTextKit2(leaf), "\(context): \(leaf) is not a TextKit 2 row owned by \(leaf.owner)",
                          file: file, line: line)
        } else {
            XCTAssertTrue(isSwiftUI(leaf), "\(context): \(leaf) is a TextKit 2 row on SwiftUI", file: file, line: line)
        }
    }

    /// Whether the section holding `left` (its first column) and `right`
    /// (a later column) lays its columns out side by side (a regular width
    /// below the accessibility sizes: the two leaves share a top and
    /// `right` starts past `left`) rather than stacked. `nil` while either
    /// leaf is not in the tree.
    func columnsSideBySide(_ left: ContainerLeaf, _ right: ContainerLeaf) -> Bool? {
        let first = element(left), second = element(right)
        guard first.exists, second.exists else { return nil }
        return abs(first.frame.minY - second.frame.minY) < 4 && second.frame.minX > first.frame.maxX
    }

    /// Whether a column leaf is drawn by TextKit 2 in an arm: under the
    /// TextKit 2 switch only while its columns stack. Side by side no
    /// family keeps the renderer (PR 4 step 4: the off-grid column probe,
    /// `TextKit2Scope.horizontalColumnKeepsRenderer`), so the column text
    /// stays SwiftUI there in both arms; so does every container body at
    /// accessibility4 and above (`atAccessibility4`: lead call C53,
    /// `TextKit2Scope.containerSizeKeepsRenderer`).
    static func columnTextKit2(_ textKit2: Bool, sideBySide: Bool, atAccessibility4: Bool = false) -> Bool {
        textKit2 && !sideBySide && !atAccessibility4
    }

    // MARK: Geometry

    /// Fully inside the viewport, give or take `slack` points.
    func isShown(_ element: XCUIElement, slack: CGFloat = 2) -> Bool {
        guard element.exists else { return false }
        let frame = element.frame
        let viewport = reader.viewport
        return frame.height > 0 && frame.minY >= viewport.minY - slack && frame.maxY <= viewport.maxY + slack
    }

    /// Any part of it inside the viewport.
    func isPartlyShown(_ element: XCUIElement) -> Bool {
        guard element.exists else { return false }
        let frame = element.frame
        let viewport = reader.viewport
        return frame.height > 0 && frame.maxY > viewport.minY && frame.minY < viewport.maxY
    }

    func waitUntilShown(_ element: XCUIElement, timeout: TimeInterval = 10) -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        repeat {
            if isShown(element) { return true }
            pause(0.25)
        } while Date() < deadline
        return isShown(element)
    }

    // MARK: Navigation

    /// Jumps to a root heading through the toolbar's Table of Contents
    /// (items are indented by level, so the match is on the title's end),
    /// then makes a short held drag so the last scroll before any switch
    /// is a gesture (as `CodeUIDriver.jump`).
    func jump(toHeading title: String, settleDrag: CGFloat = 60) {
        let contents = app.buttons["Table of Contents"]
        XCTAssertTrue(contents.waitForExistence(timeout: 5), "Table of Contents control missing")
        contents.tap()
        let item = app.buttons.matching(NSPredicate(format: "label ENDSWITH %@", title)).firstMatch
        XCTAssertTrue(item.waitForExistence(timeout: 10), "\(title) is not in the Table of Contents")
        item.tap()
        pause(1.5)
        XCTAssertTrue(waitUntilShown(reader.element(labelled: title)), "\(title) did not come into view")
        if settleDrag != 0 {
            reader.drag(by: settleDrag)
            pause(0.8)
        }
    }

    /// Drags `step` points at a time (> 0 toward the end) until `element`
    /// is fully in view, at most `maxDrags` times; `afterEachDrag` runs
    /// after every drag.
    @discardableResult
    func scroll(by step: CGFloat, until element: XCUIElement, maxDrags: Int = 30,
                afterEachDrag: () -> Void = {}) -> Bool
    {
        var drags = 0
        while !isShown(element), drags < maxDrags {
            // Once the element is in the tree, step toward it, never past it.
            var distance = step
            if element.exists {
                let frame = element.frame, viewport = reader.viewport
                if frame.minY < viewport.minY {
                    distance = -min(abs(step), viewport.minY - frame.minY + 40)
                } else if frame.maxY > viewport.maxY {
                    distance = min(abs(step), frame.maxY - viewport.maxY + 40)
                }
            }
            reader.drag(by: distance)
            pause(0.4)
            afterEachDrag()
            drags += 1
        }
        return isShown(element)
    }

    /// What `seek` did: whether the element ended in view, the drags, and
    /// how often the steering turned round (a turn means the lazy stack
    /// jumped past the target).
    struct Seek {
        var shown = false
        var drags = 0
        var turns = 0
        var figures: [String: Any] { ["shown": shown, "drags": drags, "turns": turns] }
    }

    /// containers-expand only: scrolls until `element` (at top-level block
    /// `target`, see `ContainersExpand.blockIndex(ofLabel:)`) is shown,
    /// steering by the first `CE-` label in the tree while the element is
    /// not in it. A fixed direction is not enough there: on SwiftUI the
    /// lazy stack can jump thousands of points while scrolling up past open
    /// expands (the first K7 pilot went from CE-FILL-2-022 to CE-FILL-T-026,
    /// past both open expands, in two 600 pt drags, then kept scrolling up
    /// away from CE-OPEN-2's title).
    func seek(_ element: XCUIElement, at target: Double, step: CGFloat = 600, maxDrags: Int = 40) -> Seek {
        var result = Seek()
        var direction: CGFloat = 0
        while !isShown(element), result.drags < maxDrags {
            var distance = step
            if element.exists {
                let frame = element.frame, viewport = reader.viewport
                if frame.minY < viewport.minY {
                    distance = -min(abs(step), viewport.minY - frame.minY + 40)
                } else if frame.maxY > viewport.maxY {
                    distance = min(abs(step), frame.maxY - viewport.maxY + 40)
                }
            } else if let here = shownBlockIndex() {
                distance = here > target ? -abs(step) : abs(step)
            }
            let sign: CGFloat = distance < 0 ? -1 : 1
            if direction != 0, sign != direction { result.turns += 1 }
            direction = sign
            reader.drag(by: distance)
            pause(0.4)
            result.drags += 1
        }
        result.shown = isShown(element)
        return result
    }

    /// containers-expand only: the median block index of the `CE-` labels
    /// on screen, from one snapshot of the tree (rows the lazy stack keeps
    /// off screen do not count); nil when none is on screen.
    func shownBlockIndex() -> Double? {
        guard let root = try? app.snapshot() else { return nil }
        let viewport = reader.viewport
        var indices: [Double] = []
        var stack: [any XCUIElementSnapshot] = [root]
        while let node = stack.popLast() {
            if node.label.hasPrefix("CE-"), node.frame.intersects(viewport),
               let index = ContainersExpand.blockIndex(ofLabel: node.label)
            {
                indices.append(index)
            }
            stack.append(contentsOf: node.children)
        }
        guard !indices.isEmpty else { return nil }
        return indices.sorted()[indices.count / 2]
    }

    // MARK: Expands

    /// The expand button labelled `title`.
    func expandButton(_ title: String) -> XCUIElement {
        app.buttons.matching(NSPredicate(format: "label == %@", title)).firstMatch
    }

    /// The expand's accessibility value ("Expanded" / "Collapsed"), nil
    /// when the button is not in the tree.
    func expandValue(_ title: String) -> String? {
        let button = expandButton(title)
        return button.exists ? button.value as? String : nil
    }

    /// Brings the expand titled `title` into view (`step` > 0: it lies
    /// toward the end) and taps it when its value is not `open`'s.
    /// Returns whether the value then reads as wanted.
    @discardableResult
    func setExpand(_ title: String, open: Bool, step: CGFloat = 600, maxDrags: Int = 30) -> Bool {
        let button = expandButton(title)
        guard scroll(by: step, until: button, maxDrags: maxDrags) else { return false }
        let wanted = open ? "Expanded" : "Collapsed"
        if (button.value as? String) != wanted {
            button.tap()
        }
        let deadline = Date().addingTimeInterval(10)
        while (button.value as? String) != wanted, Date() < deadline {
            pause(0.25)
        }
        return (button.value as? String) == wanted
    }

    // MARK: Search

    /// Opens Find in Page if needed, runs `query` and returns the counter
    /// once the scan has finished ("current / total", or "0").
    func search(_ query: String) -> String {
        let field = app.textFields[ReaderDriver.Identifier.searchField]
        if !field.exists {
            app.buttons["Find in Page"].tap()
        }
        XCTAssertTrue(field.waitForExistence(timeout: 5), "search field missing")
        field.tap()
        if let current = field.value as? String, !current.isEmpty, current != "Find in page" {
            field.typeText(String(repeating: XCUIKeyboardKey.delete.rawValue, count: current.count))
        }
        field.typeText(query + "\n")
        let counter = app.staticTexts[ReaderDriver.Identifier.searchCounter]
        XCTAssertTrue(counter.waitForExistence(timeout: 10), "search counter missing for \(query)")
        pause(1.5)
        return counter.exists ? counter.label : "missing"
    }

    /// The search bar's Done: clears the search and closes the bar.
    func clearSearch() {
        let field = app.textFields[ReaderDriver.Identifier.searchField]
        XCTAssertTrue(field.exists, "no search to clear")
        let row = field.frame
        let done = app.buttons.matching(NSPredicate(format: "label == %@", "Done")).allElementsBoundByIndex
            .first { abs($0.frame.midY - row.midY) < 30 }
        XCTAssertNotNil(done, "the search bar's Done button is missing")
        done?.tap()
        XCTAssertTrue(reader.waitForDisappearance(of: field, timeout: 5), "the search bar did not close")
        pause(1)
    }

    // MARK: Points

    func tap(at point: CGPoint) {
        app.coordinate(withNormalizedOffset: .zero).withOffset(CGVector(dx: point.x, dy: point.y)).tap()
    }

    /// Each link's span relative to its text's top-left corner, from the
    /// last arm whose tree exposed the link element (SwiftUI's). A TextKit 2
    /// row exposes no link element, and it lays the text out as SwiftUI does
    /// (the parity suites), so a later arm taps the same glyphs there.
    static var linkSpans: [String: CGRect] = [:]

    /// Screen points on `link`'s glyphs, best first: the centre of the link
    /// element SwiftUI exposes inside the text when there is one (clamped
    /// to the text's frame); else the span an earlier arm's link element
    /// had in the same text (`linkSpans`); else an estimate along the
    /// text's first line.
    func linkPoints(_ link: ContainerLink, in text: XCUIElement) -> [CGPoint] {
        let frame = text.frame
        let lineHeight: CGFloat = 20.5
        func points(_ span: CGRect) -> [CGPoint] {
            guard span.height > lineHeight * 1.5 else { return [CGPoint(x: span.midX, y: span.midY)] }
            return [CGPoint(x: span.minX + 8, y: span.maxY - lineHeight / 2),
                    CGPoint(x: span.maxX - 8, y: span.minY + lineHeight / 2)]
        }
        let candidates = app.links.matching(NSPredicate(format: "label == %@", link.linkText)).allElementsBoundByIndex
        if let element = candidates.first(where: { $0.frame.intersects(frame) }) {
            let span = element.frame.intersection(frame)
            Self.linkSpans[link.leaf.owner + "|" + link.linkText] = span.offsetBy(dx: -frame.minX, dy: -frame.minY)
            return points(span)
        }
        if let relative = Self.linkSpans[link.leaf.owner + "|" + link.linkText] {
            return points(relative.offsetBy(dx: frame.minX, dy: frame.minY))
        }
        return [CGPoint(x: frame.midX, y: frame.minY + min(frame.height, 20) / 2)]
    }

    // MARK: About This Build

    func openAbout() {
        reader.openRendererMenu()
        let about = app.descendants(matching: .any).matching(identifier: ReaderDriver.Identifier.about).firstMatch
        XCTAssertTrue(about.waitForExistence(timeout: Self.aboutTimeout), "About This Build… missing from the menu")
        about.tap()
        XCTAssertTrue(app.staticTexts[ReaderDriver.Identifier.buildVersion].waitForExistence(timeout: Self.aboutTimeout),
                      "About This Build did not open")
    }

    func closeAbout() {
        let done = app.buttons[ReaderDriver.Identifier.buildDone]
        XCTAssertTrue(done.waitForExistence(timeout: Self.aboutTimeout), "Done button missing")
        done.tap()
        XCTAssertTrue(reader.waitForDisappearance(
            of: app.staticTexts[ReaderDriver.Identifier.buildVersion], timeout: Self.aboutTimeout
        ), "About sheet did not dismiss")
        pause(0.5)
    }

    /// One About count (opens and closes About), waiting up to 5 s for
    /// `condition` with two agreeing reads; nil when the sheet has no such
    /// field (a build without PR 4's counters).
    func aboutCount(_ identifier: String, until condition: (Int) -> Bool = { _ in true }) -> Int? {
        openAbout()
        defer { closeAbout() }
        let field = app.staticTexts[identifier]
        reader.revealAboutField(field)
        guard field.waitForExistence(timeout: 5) else { return nil }
        return reader.readCount(identifier, until: condition, settled: true)
    }

    /// The probe's four fields (opens and closes About). Fails, naming the
    /// hook, when the demo has no `-interactionProbe`.
    func readProbe() -> ContainerProbe? {
        openAbout()
        defer { closeAbout() }
        let dispatches = app.staticTexts[ContainerProbe.Identifier.taskDispatches]
        let opens = app.staticTexts[ContainerProbe.Identifier.urlOpens]
        var swipes = 0
        while !(dispatches.exists && opens.exists), swipes < 4 {
            app.swipeUp()
            pause(0.5)
            swipes += 1
        }
        guard dispatches.waitForExistence(timeout: 5), opens.waitForExistence(timeout: 5) else {
            XCTFail("About This Build has no \(ContainerProbe.Identifier.taskDispatches): "
                + "the demo's -interactionProbe hook is missing")
            return nil
        }
        pause(0.5)
        func text(_ identifier: String) -> String {
            let field = app.staticTexts[identifier]
            return field.exists ? field.label : ""
        }
        return ContainerProbe(
            taskDispatches: Int(dispatches.label) ?? -1,
            taskLast: text(ContainerProbe.Identifier.taskLast),
            urlOpens: Int(text(ContainerProbe.Identifier.urlOpens)) ?? -1,
            urlLast: text(ContainerProbe.Identifier.urlLast)
        )
    }

    /// Seconds from `start` until `element` exists, or nil after `timeout`.
    /// Polls `exists` every 50 ms: `waitForExistence` first checks about
    /// 1 s after it starts and then about once a second, which would round
    /// every K7/K8 open time up to the next check (the first K8 pilot's log:
    /// the first check came 1.06 s after the wait began).
    static func seconds(until element: XCUIElement, since start: Date, timeout: TimeInterval) -> Double? {
        let deadline = start.addingTimeInterval(timeout)
        while Date() < deadline {
            if element.exists { return Date().timeIntervalSince(start) }
            Thread.sleep(forTimeInterval: 0.05)
        }
        return element.exists ? Date().timeIntervalSince(start) : nil
    }
}

// MARK: - Test case helpers

@MainActor
extension XCTestCase {
    func containerUIStep(_ name: String, _ body: () throws -> Void) throws {
        try XCTContext.runActivity(named: name) { _ in try body() }
    }

    func containerUINote(_ text: String) {
        XCTContext.runActivity(named: text) { _ in }
    }

    func containerUIAttach(_ app: XCUIApplication, _ name: String) {
        let attachment = XCTAttachment(screenshot: app.screenshot())
        attachment.name = name
        attachment.lifetime = .keepAlways
        add(attachment)
    }

    func containerUIAttach(text: String, _ name: String) {
        let attachment = XCTAttachment(string: text)
        attachment.name = name
        attachment.lifetime = .keepAlways
        add(attachment)
    }
}
